window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[298]={"id":"298","numero":298,"titre":"Cancer ORL — Tumeurs VADS, cavum, naso-sinusiennes","objectifs":[{"id":"298-1","rang":"A","rubrique":"Définition","titre":"Connaître les généralités anatomiques des cancers des voies aérodigestives supérieures (VADS)","contenu":"<p>Les <span class=\"kw-def\">voies aérodigestives supérieures</span> (VADS) assurent <strong>alimentation</strong> (mastication, déglutition), <strong>articulation</strong>, <strong>phonation</strong> et <strong>respiration</strong>, tout en protégeant le poumon des risques d'inhalation. On les divise en <strong>3 sites principaux</strong> : <span class=\"kw-def\">cavité orale</span>, <span class=\"kw-def\">pharynx</span> (nasopharynx/cavum, oropharynx, hypopharynx) et <span class=\"kw-def\">larynx</span>. Les cavités <span class=\"kw-def\">naso-sinusiennes</span> (fosses nasales, sinus ethmoïdaux, maxillaires, sphénoïdal) leur sont rattachées en termes carcinologiques.</p>\n      <table >\n        <thead>\n          <tr><th>Région</th><th>Sous-sites anatomiques</th><th>Drainage ganglionnaire principal (Robbins)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Cavité orale</span></td>\n            <td><strong>Lèvres rouges</strong>, vestibule labial/jugal, <strong>gencives</strong>, régions rétromolaires, <strong>plancher buccal</strong>, <strong>langue mobile</strong> (jusqu'au « V » lingual), <strong>palais dur</strong></td>\n            <td>Aires <span class=\"kw-def\">I</span> (Ia sous-mentale, Ib sous-mandibulaire), <span class=\"kw-def\">II</span>, <span class=\"kw-def\">III</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Oropharynx</span></td>\n            <td><strong>Voile du palais</strong> et piliers, <strong>amygdales palatines</strong>, <strong>base de langue</strong>, vallécules, sillons amygdalo-glosses, paroi pharyngée postérieure</td>\n            <td>Aires <span class=\"kw-def\">II</span> (sous-angulo-mandibulaire) et <span class=\"kw-def\">III</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Hypopharynx</span></td>\n            <td><strong>Sinus piriformes</strong>, paroi pharyngée postérieure, <strong>région rétrocricoaryténoïdienne</strong> jusqu'à la bouche œsophagienne (bord inférieur de C6)</td>\n            <td>Aires <span class=\"kw-def\">II</span>, <span class=\"kw-def\">III</span>, <span class=\"kw-def\">IV</span> (révélatrice dans 1/3 des cas)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Larynx</span></td>\n            <td><strong>Sus-glottique</strong> : épiglotte, plis aryépiglottiques, aryténoïdes, bandes ventriculaires ; <strong>glottique</strong> : cordes vocales, commissure antérieure ; <strong>sous-glottique</strong> : jusqu'au cricoïde</td>\n            <td><strong>Glotte = peu lymphophile</strong> (T1) ; sus-glotte et sous-glotte = aires <span class=\"kw-def\">II</span>, <span class=\"kw-def\">III</span>, <span class=\"kw-def\">VI</span> (prélaryngée)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Nasopharynx / cavum</span></td>\n            <td><strong>Choanes</strong> en avant, base du crâne (corps du sphénoïde) en haut, paroi postérieure (végétations adénoïdes), <strong>torus tubaires</strong> latéralement (trompe d'Eustache)</td>\n            <td>Aires <span class=\"kw-def\">II</span> et <span class=\"kw-def\">V</span> (haute, postérieure, rétromandibulaire-parotidienne, <strong>souvent bilatérale</strong>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Fosses nasales · sinus</span></td>\n            <td><strong>Sinus ethmoïdaux</strong> (entre les 2 orbites, sous l'étage antérieur de la base du crâne), <strong>maxillaire</strong>, <strong>sphénoïdal</strong>, cornets, fente olfactive</td>\n            <td><strong>Peu lymphophiles</strong> (sauf ethmoïde) — extension locorégionale prédominante (orbite, endocrâne)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Classification de Robbins en 6 zones du cou</strong> : <span class=\"kw-def\">I</span> sous-mentale/sous-mandibulaire (cavité orale, face, fosses nasales) ; <span class=\"kw-def\">II</span> sous-angulo-mandibulaire et sus-/rétro-spinale (nerf accessoire) ; <span class=\"kw-def\">III</span> jugulo-carotidienne moyenne ; <span class=\"kw-def\">IV</span> sus-claviculaire entre cricoïde et clavicule ; <span class=\"kw-def\">V</span> spinale et cervicale transverse ; <span class=\"kw-def\">VI</span> prélaryngée (drainage du larynx).</p>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Les cancers des VADS sont <span class=\"kw-alerte\">lymphophiles</span> — leur traitement comportera donc systématiquement celui des aires ganglionnaires (curage cervical). <strong>Seule exception</strong> : le <span class=\"kw-def\">cancer glottique T1</span>, faiblement lymphophile aux stades précoces.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 90 — Pathologie des glandes salivaires · 293 — Anapath</em></p>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/who-classification-of-head-and-neck-tumors","label":"Radiopaedia : Who classification of head and neck tumors"},{"href":"https://radiopaedia.org/articles/oral-cavity-1","label":"Radiopaedia : Oral cavity 1"},{"href":"https://radiopaedia.org/articles/buccal-space?embed_domain=hackmd.io/@yipuafecsl2jsu8smr5njq/bnjhjgjghjghjgh&lang=us","label":"Radiopaedia : Buccal space"},{"href":"https://radiopaedia.org/articles/pharynx","label":"Radiopaedia : Pharynx"},{"href":"https://radiopaedia.org/articles/larynx","label":"Radiopaedia : Larynx"},{"href":"https://cerf.radiologie.fr/sites/cerf.radiologie.fr/files/files/enseignement/pdf/7%20MM%20AIRES%20GANGLIONNAIRES%20CERVICALES.pdf","label":"7 mm aires ganglionnaires cervicales"},{"href":"https://radiopaedia.org/articles/cervical-lymph-node-metastasis-radiologic-criteria","label":"Radiopaedia : Cervical lymph node metastasis radiologic criteria"},{"href":"https://radiopaedia.org/articles/mandibular-osteoradionecrosis","label":"Radiopaedia : Mandibular osteoradionecrosis"},{"href":"https://radiopaedia.org/articles/oropharyngeal-squamous-cell-carcinoma","label":"Radiopaedia : Oropharyngeal squamous cell carcinoma"},{"href":"https://radiopaedia.org/articles/hypopharyngeal-squamous-cell-carcinoma","label":"Radiopaedia : Hypopharyngeal squamous cell carcinoma"},{"href":"https://radiopaedia.org/articles/squamous-cell-carcinoma-of-the-larynx","label":"Radiopaedia : Squamous cell carcinoma of the larynx"},{"href":"https://radiopaedia.org/articles/nasopharyngeal-carcinoma","label":"Radiopaedia : Nasopharyngeal carcinoma"},{"href":"https://radiopaedia.org/articles/sinonasal-adenocarcinoma","label":"Radiopaedia : Sinonasal adenocarcinoma"}]},{"id":"298-2","rang":"B","rubrique":"Définition","titre":"Connaître les principaux types histologiques des tumeurs bénignes et malignes ORL par localisation (hors glandes salivaires)","contenu":"<p>Le <span class=\"kw-def\">carcinome épidermoïde</span> représente <span class=\"kw-chiffre\">&gt; 90-95 %</span> des cancers des VADS (cavité buccale, oropharynx, hypopharynx, larynx, lèvres). Les exceptions histologiques majeures sont à connaître pour chaque localisation, car elles conditionnent terrain, FDR et pronostic.</p>\n      <table >\n        <thead>\n          <tr><th>Localisation</th><th>Histologie principale</th><th>FDR / terrain</th><th>Évolution</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Cavité buccale</strong></td>\n            <td><span class=\"kw-def\">Carcinome épidermoïde</span> ± différencié (<span class=\"kw-chiffre\">&gt; 90 %</span>)</td>\n            <td>Tabac + alcool, lésions précancéreuses (leucoplasie, érythroplasie, lichen plan érosif)</td>\n            <td>De novo (<span class=\"kw-chiffre\">85 %</span>) ou dégénérescence d'une LPM (<span class=\"kw-chiffre\">15 %</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Oropharynx</strong></td>\n            <td>Carcinome épidermoïde (<span class=\"kw-chiffre\">90 %</span>) ; <span class=\"kw-etio\">lymphome non hodgkinien</span> possible sur amygdales palatines/linguales ; <span class=\"kw-etio\">carcinome adénoïde kystique</span> (origine salivaire, rare)</td>\n            <td><strong>HPV-16</strong> +++ surtout amygdale (<span class=\"kw-chiffre\">35-40 %</span> HPV-induits), tabac + alcool</td>\n            <td>HPV+ = <span class=\"kw-alerte\">pronostic meilleur</span> à stade égal</td>\n          </tr>\n          <tr>\n            <td><strong>Hypopharynx · larynx</strong></td>\n            <td>Carcinome épidermoïde (<span class=\"kw-chiffre\">&gt; 90-95 %</span>)</td>\n            <td>Tabac (+++ larynx), alcool ; laryngites chroniques → dysplasie → cancer in situ → infiltrant</td>\n            <td>Hypopharynx : <span class=\"kw-alerte\">pronostic sombre</span> (<span class=\"kw-chiffre\">20 %</span> survie à<span class=\"kw-chiffre\"> 5 ans</span>). Larynx :<span class=\"kw-chiffre\"> 60 %</span> à<span class=\"kw-chiffre\"> 5 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Nasopharynx / cavum</strong></td>\n            <td><span class=\"kw-def\">UCNT</span> (<em>Undifferentiated Carcinoma of Nasopharyngeal Type</em>) — carcinome indifférencié +++ ; lymphome non hodgkinien (<span class=\"kw-chiffre\">10-20 %</span>)</td>\n            <td><span class=\"kw-etio\">EBV</span> constamment présent (hybridation in situ), géographie (Maghreb, Asie SE, Alaska)</td>\n            <td>Survie globale <span class=\"kw-chiffre\">~30 %</span> à<span class=\"kw-chiffre\"> 5 ans</span> ; <strong>pas de lien tabac-alcool</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Ethmoïde · fente olfactive</strong></td>\n            <td><span class=\"kw-def\">Adénocarcinome</span> +++ (majorité) ; carcinome épidermoïde, mélanome muqueux, lymphome, sarcome (plus rares, hors FDR pro)</td>\n            <td><span class=\"kw-etio\">Poussières de bois</span> (menuisier, ébéniste), nickel, formaldéhyde, nitrosamines, goudrons de houille — <strong>maladies professionnelles</strong></td>\n            <td>T1 : survie <span class=\"kw-chiffre\">5 ans</span> <span class=\"kw-chiffre\">~100 %</span> ; T4b :<span class=\"kw-chiffre\"> 13 %</span> à<span class=\"kw-chiffre\"> 3 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong>Sinus maxillaire · cloison · sphénoïde</strong></td>\n            <td>Carcinome épidermoïde ± différencié</td>\n            <td>Sujet âgé, signes tardifs (mobilité molaires secteur 1-2)</td>\n            <td>Pronostic plus mauvais que l'ethmoïde ; cloison nasale = <span class=\"kw-alerte\">très lymphophile</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Lésions précancéreuses (LPM)</strong> à connaître par localisation :</p>\n      <ul>\n        <li><strong>Cavité buccale :</strong> <span class=\"kw-def\">leucoplasie / leucokératose</span> (hyperkératose tabagique, formes inhomogènes à risque), <span class=\"kw-def\">érythroplasie de Queyrat</span> (<span class=\"kw-alerte\">dégénérescence systématique</span>), <span class=\"kw-def\">lichen plan érosif</span> (surveillance semestrielle), candidose chronique hyperplasique, papillomatose orale floride (leucoplasie verruqueuse proliférative — évolution vers carcinome verruqueux), chéilite actinique chronique (<span class=\"kw-chiffre\">70 %</span> des cancers de lèvre), fibrose orale sous-muqueuse.</li>\n        <li><strong>Larynx :</strong> dysplasie, leucoplasie, érythroplasie, papillomatose laryngée.</li>\n        <li><strong>Hypopharynx :</strong> <span class=\"kw-def\">maladie de Plummer-Vinson</span> (Kelly-Patterson) — dysphagie + risque de carcinome œsophagien.</li>\n      </ul>\n      <p><strong>Tumeurs bénignes</strong> (rare cadre nosologique) : polype antrochoanal, fibrome nasopharyngien de la puberté masculine (cavum), végétations adénoïdes hypertrophiques, papillomes, hémangiomes. <span class=\"kw-alerte\">Hors champ : glandes salivaires</span> (traité dans l'item dédié).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 90 — Pathologie des glandes salivaires · 293 — Anapath · 300 — Tumeur col-corps utérin (autre HPV-induit)</em></p>","frequence":3},{"id":"298-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître l'histoire naturelle et les facteurs de risque des cancers VADS","contenu":"<p>L'<strong>histoire naturelle</strong> des cancers VADS suit une séquence stéréotypée : exposition chronique aux carcinogènes → <span class=\"kw-def\">lésions précancéreuses</span> (leucoplasie, érythroplasie, dysplasie) → <strong>carcinome in situ</strong> → <strong>carcinome infiltrant</strong>. La progression de novo (<span class=\"kw-chiffre\">85 %</span>) prédomine, mais <span class=\"kw-chiffre\">15 %</span> naissent sur une LPM. Extension <span class=\"kw-alerte\">locorégionale</span> par contiguïté et par voie lymphatique (lymphophilie marquée — <em>sauf cancer glottique T1</em>), puis métastases hématogènes <strong>tardives</strong> (<span class=\"kw-chiffre\">10 %</span>) : <span class=\"kw-clinique\">poumon</span> +++ &gt; os &gt; foie &gt; cerveau &gt; <span class=\"kw-clinique\">vessie</span>.</p>\n      <p>Notion centrale = <span class=\"kw-def\">champ de cancérisation</span> : le carcinogène expose simultanément toute la muqueuse aérodigestive supérieure → <strong>cancers synchrones</strong> (œsophage, poumon, autre VADS) et <strong>métachrones</strong> (<span class=\"kw-chiffre\">&gt; 20 %</span> 2nd VADS, <span class=\"kw-chiffre\">10 %</span> bronchique) → justifie la <span class=\"kw-def\">panendoscopie</span> systématique au bilan initial.</p>\n      <table >\n        <thead>\n          <tr><th>Facteur de risque</th><th>Mécanisme · particularités</th><th>Topographie préférentielle</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Tabac</span> + <span class=\"kw-etio\">alcool</span></td>\n            <td><strong>Synergie multiplicative</strong> (RR &gt;30 si association) = principal FDR. Arrêt tabac + ↓ alcool ⇒ <span class=\"kw-chiffre\">-2/3</span> du risque ; retour au niveau non-fumeur après <span class=\"kw-chiffre\">20 ans</span> d'arrêt</td>\n            <td>Tabac → <strong>larynx</strong> (+++) ; alcool → cavité buccale, oropharynx, hypopharynx</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">HPV oncogène</span> (sérotype 16 ++, 18)</td>\n            <td>IST muqueuse ; impliqué dans <span class=\"kw-chiffre\">25 %</span> des cancers ORL ; diagnostic par <span class=\"kw-bio\">PCR</span> ou <span class=\"kw-bio\">immunohistochimie P16</span> ; <strong>terrain jeune</strong> (<span class=\"kw-chiffre\">45-55 ans</span>), parité H/F, sans alcoolo-tabagisme ; <span class=\"kw-alerte\">pronostic meilleur à stade égal</span></td>\n            <td><strong>Oropharynx</strong> surtout <strong>amygdale palatine</strong> (<span class=\"kw-chiffre\">35-40 %</span> HPV+) et base de langue</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">EBV</span> (virus d'Epstein-Barr)</td>\n            <td><strong>Constamment présent</strong> dans l'UCNT ; recherche par <span class=\"kw-bio\">hybridation in situ</span> sur prélèvement tumoral ; ↑ AC anti-EBV proportionnelle au volume/stade/récidive</td>\n            <td><strong>Cavum / nasopharynx</strong> uniquement (UCNT)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Expositions professionnelles</span></td>\n            <td><strong>Poussières de bois</strong> (menuisier, ébéniste — <em>maladie professionnelle</em>) · <strong>nickel</strong> · <strong>formaldéhyde</strong> (anatomopathologistes, embaumeurs) · acide chromique · aldéhyde formique · nitrosamines · goudrons de houille · amiante</td>\n            <td><strong>Ethmoïde</strong> ++ (adénocarcinome) ; cavum (formaldéhyde)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Autres FDR</span></td>\n            <td><strong>Carences vitaminiques</strong> A et C (alcoolo-tabagique souvent carencé) <br><strong>Plaies chroniques</strong> (prothèse dentaire mal adaptée) <br><strong>Immunosuppression</strong> (greffés, VIH, immunosuppresseurs) <br><strong>Mauvaise hygiène</strong> bucco-dentaire <br><strong>RGO chronique</strong> (larynx)</td>\n            <td>Cavité buccale +++ pour les plaies chroniques</td>\n          </tr>\n          <tr>\n            <td><strong>Facteurs protecteurs</strong></td>\n            <td>Consommation d'aliments riches en vitamines (fruits, légumes) — effet protecteur selon CMF</td>\n            <td>Toutes localisations VADS</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Une <span class=\"kw-clinique\">adénopathie cervicale isolée non inflammatoire</span> chez un sujet à risque alcoolo-tabagique impose la recherche d'un cancer primitif des VADS (panendoscopie + cavoscopie). <span class=\"kw-alerte\">Biopsie de l'adénopathie interdite</span> en première intention (risque d'essaimage tumoral et de remaniement cicatriciel).\n      </div>\n      <div class=\"callout callout-info\">\n        <strong>Cas particulier HPV+.</strong> Une <span class=\"kw-clinique\">adénopathie cervicale kystique jugulo-carotidienne</span> chez un sujet de <span class=\"kw-chiffre\">&gt; 40 ans</span>, <strong>même non alcoolo-tabagique</strong>, doit faire évoquer une métastase d'un cancer oropharyngé HPV-induit (amygdale, base de langue) → ne pas la confondre avec un kyste amygdaloïde bénin.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction Tabac · 76 — Addiction à l'alcool · 146 — Vaccination · 162 — IST · 300 — Tumeur col-corps utérin</em></p>","frequence":6},{"id":"298-4","rang":"B","rubrique":"Épidémiologie","titre":"Connaître les généralités épidémiologiques des cancers VADS","contenu":"<p>Les cancers des VADS représentent <span class=\"kw-chiffre\">~15 000</span> nouveaux cas/an en France, <span class=\"kw-chiffre\">3 600</span> décès annuels. <strong>4ᵉ cancer de l'homme</strong> (<span class=\"kw-chiffre\">15 %</span> des cancers, 11 000 cas) et 10ᵉ de la femme (<span class=\"kw-chiffre\">2 %</span>, 4 300 cas). Terrain socio-économique souvent défavorisé.</p>\n      <table >\n        <thead>\n          <tr><th>Paramètre</th><th>Valeur</th><th>Tendance</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Sex-ratio global</td>\n            <td>Prédominance masculine <span class=\"kw-chiffre\">~75-80 %</span> (3-4 H / 1 F)</td>\n            <td><strong>En baisse</strong> : ↓ chez l'homme (recul tabac/alcool), ↑ chez la femme (rattrapage tabac/alcool)</td>\n          </tr>\n          <tr>\n            <td>Âge médian au diagnostic</td>\n            <td><span class=\"kw-chiffre\">60 ans</span> chez l'homme, <span class=\"kw-chiffre\">64 ans</span> chez la femme (pic <span class=\"kw-chiffre\">50-70 ans</span>)</td>\n            <td><strong>Rajeunissement</strong> sur l'oropharynx HPV+ (<span class=\"kw-chiffre\">45-55 ans</span>)</td>\n          </tr>\n          <tr>\n            <td>Géographie française</td>\n            <td>Incidence ↑ dans le <strong>Nord</strong> et l'<strong>Est</strong> (consommation éthylique)</td>\n            <td>Gradient en lien direct avec l'alcoolisme régional</td>\n          </tr>\n          <tr>\n            <td>Répartition par site</td>\n            <td><strong>Larynx <span class=\"kw-chiffre\">35 %</span></strong> · cavité buccale <span class=\"kw-chiffre\">25 %</span> · hypopharynx <span class=\"kw-chiffre\">25 %</span> · oropharynx <span class=\"kw-chiffre\">15 %</span> · cavum &lt;<span class=\"kw-chiffre\"> 1 %</span> · nasosinus &lt;<span class=\"kw-chiffre\"> 1 %</span></td>\n            <td>↑ <strong>oropharynx HPV+</strong> (sujets plus jeunes)</td>\n          </tr>\n          <tr>\n            <td>Survie globale à<span class=\"kw-chiffre\"> 5 ans</span></td>\n            <td><span class=\"kw-chiffre\">35 %</span> chez l'homme · <span class=\"kw-chiffre\">50 %</span> chez la femme (toutes localisations) — <strong>stable depuis <span class=\"kw-chiffre\">30 ans</span></strong></td>\n            <td>Pronostic conditionné par le <strong>diagnostic précoce</strong>. Larynx ~<span class=\"kw-chiffre\">60 %</span> · hypopharynx ~<span class=\"kw-chiffre\">20 %</span> · cavum ~<span class=\"kw-chiffre\">30 %</span></td>\n          </tr>\n          <tr>\n            <td>Cavum (UCNT)</td>\n            <td><strong>Incidence :</strong> 1/100 000 en Europe ; <br><strong>Pic d'âge :</strong><span class=\"kw-chiffre\"> 40-50 ans</span> ; <br><strong>Sex-ratio :</strong> 3 H / 1 F (moins marqué)</td>\n            <td>Zones à haut risque : <strong>Maghreb / pourtour méditerranéen</strong>, Asie du Sud-Est, Alaska · formes familiales <span class=\"kw-chiffre\">10 %</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Tout symptôme d'appel des VADS et de la région cervicale (3D : dysphagie, dysphonie, dyspnée, otalgie réflexe, adénopathie), surtout s'il est <span class=\"kw-alerte\">fixe, unilatéral et persistant &gt; 3 semaines</span>, doit faire évoquer un cancer VADS — particulièrement sur terrain alcoolo-tabagique.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — Epidémiologie cancers</em></p>","frequence":1},{"id":"298-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques des cancers de la cavité buccale, des cancers nasosinusiens ou des cancers VADS","contenu":"<p>Tout symptôme d'appel des VADS persistant <span class=\"kw-alerte\">&gt; 15 jours (souvent retenu &gt; 3 semaines)</span>, <strong>fixe</strong>, <strong>unilatéral</strong>, surtout sur terrain alcoolo-tabagique, doit faire évoquer un cancer. <strong>Triade « 3D »</strong> : <span class=\"kw-clinique\">dysphagie</span>, <span class=\"kw-clinique\">dysphonie</span>, <span class=\"kw-clinique\">dyspnée</span> — auxquels s'ajoutent <span class=\"kw-clinique\">douleur</span>, <span class=\"kw-clinique\">otalgie réflexe</span> (innervation X-IX-V), <span class=\"kw-clinique\">adénopathie cervicale</span> et <span class=\"kw-clinique\">tuméfaction</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Localisation</th><th>Signes d'appel cliniques</th><th>ADP / drapeau rouge</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Cavité buccale</strong></td>\n            <td><strong>Précoces :</strong> <span class=\"kw-clinique\">glossodynies</span>, gêne buccale, douleur, <span class=\"kw-clinique\">otalgie réflexe</span>, odynophagie, gingivorragie. <br><strong>Tardifs :</strong> mobilité dentaire (« dents flottantes » par ostéolyse), instabilité prothétique, <span class=\"kw-clinique\">protraction linguale déviée</span> du côté tumoral (XII ou muscles linguaux), <span class=\"kw-alerte\">anesthésie V3 (signe de Vincent)</span> dans les formes gingivomandibulaires, <span class=\"kw-clinique\">trismus</span> (ptérygoïdien médial), dysarthrie, dysphagie haute</td>\n            <td>ADP <strong>Ia/Ib sous-mentale/sous-mandibulaire</strong>, dure, ± fixée</td>\n          </tr>\n          <tr>\n            <td><strong>Oropharynx</strong></td>\n            <td><span class=\"kw-clinique\">Gêne pharyngée unilatérale</span> à la déglutition, <span class=\"kw-clinique\">otalgie réflexe unilatérale</span>, <span class=\"kw-clinique\">dysphagie haute</span>, troubles de la mobilité linguale. Signes souvent <strong>discrets</strong></td>\n            <td>ADP <strong>IIa sous-angulo-maxillaire</strong>, dure, ± fixée. <br><span class=\"kw-alerte\">ADP kystique chez &gt; 40 ans → suspecte HPV+</span></td>\n          </tr>\n          <tr>\n            <td><strong>Hypopharynx</strong></td>\n            <td><strong>Précoces :</strong> gêne pharyngée latéralisée, <span class=\"kw-clinique\">dysphagie haute progressive</span>, <span class=\"kw-clinique\">otalgie réflexe unilatérale</span> (X). <br><strong>Tardifs (diagnostic tardif fréquent) :</strong> dysphonie, dyspnée laryngée (envahissement laryngé), AEG, amaigrissement</td>\n            <td>ADP <strong>II-III-IV</strong> indurée, <span class=\"kw-alerte\">révélatrice dans 1/3 des cas</span></td>\n          </tr>\n          <tr>\n            <td><strong>Larynx</strong></td>\n            <td><span class=\"kw-alerte\">Dysphonie persistante &gt; 3 sem = drapeau rouge</span> (maître symptôme, glotte). <br><strong>Glotte :</strong> dysphonie +++, dyspnée plus tardive. <br><strong>Sus-glotte :</strong> dysphagie, gêne pharyngée (tardifs, moins évocateurs). <br><strong>Sous-glotte :</strong> <span class=\"kw-clinique\">dyspnée laryngée tardive</span> (bradypnée inspiratoire + stridor/cornage = <span class=\"kw-alerte\">urgence thérapeutique</span>)</td>\n            <td>ADP <strong>tardive et rare</strong> dans la glotte T1 (peu lymphophile)</td>\n          </tr>\n          <tr>\n            <td><strong>Cavum / nasopharynx</strong></td>\n            <td><strong>Signes rhinologiques (<span class=\"kw-chiffre\">20 %</span>) :</strong> obstruction nasale unilatérale, épistaxis, rhinorrhée. <br><strong>Signes otologiques (<span class=\"kw-chiffre\">25 %</span>) :</strong> <span class=\"kw-alerte\">otite séreuse unilatérale adulte = cavum jusqu'à preuve du contraire</span>, hypoacousie de transmission, autophonie, bourdonnements. <br><strong>Signes neurologiques (<span class=\"kw-chiffre\">10-15 %</span>) :</strong> paralysies oculomotrices (sinus caverneux), névralgie du V (foramen ovale, V3), névralgie du IX, céphalées persistantes</td>\n            <td>ADP <strong>cervicales hautes/postérieures, rétromandibulaire-parotidienne-sous-mastoïdienne, souvent bilatérale (<span class=\"kw-chiffre\">50-90 %</span>)</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Ethmoïde · nasosinus</strong></td>\n            <td><strong>Syndrome nasal :</strong> obstruction nasale unilatérale <span class=\"kw-chiffre\">(100 %)</span> permanente résistante, <span class=\"kw-alerte\">épistaxis unilatérale spontanée répétée (35 %)</span>, hypo-/anosmie (<span class=\"kw-chiffre\">35 %</span>), rhinorrhée mucopurulente striée de sang (<span class=\"kw-chiffre\">30 %</span>). <br><strong>Syndrome ophtalmologique (tardif) :</strong> exophtalmie irréductible, ptosis, paralysie oculomotrice, diplopie, œdème paupière supérieure, dacryocystite. <br><strong>Syndrome neurologique :</strong> céphalées, <span class=\"kw-clinique\">névralgie faciale du V</span></td>\n            <td>Évolution surtout <strong>locorégionale</strong> (orbite, endocrâne). ADP rare (~<span class=\"kw-chiffre\">10 %</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Sinus maxillaire</strong></td>\n            <td><strong>Syndrome rhinosinusien :</strong> obstruction nasale unilatérale, pesanteur/douleur en regard du sinus, épistaxis récidivantes, rhinorrhée fétide. <br><strong>Bucco-dentaire :</strong> douleurs dentaires pulpaires, ulcération gingivale hémorragique, <span class=\"kw-alerte\">mobilité molaires secteur 1-2 nouvellement apparue = drapeau rouge</span>. <br><strong>Tumoral :</strong> tuméfaction de la fosse canine/joue, hypoesthésie V2</td>\n            <td>Diagnostic <strong>tardif</strong> sur sujet âgé</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Examen ORL clinique systématique</strong> : inspection endobuccale/endopharyngée, palpation bidigitale, <span class=\"kw-def\">nasofibroscopie souple</span> (consultation), examen otoscopique, palpation des aires ganglionnaires. Deux formes lésionnelles à reconnaître :</p>\n      <ul>\n        <li><strong>Tumeur bourgeonnante :</strong> lésion en volume, <span class=\"kw-clinique\">sans muqueuse de recouvrement</span>, friable, hémorragique au contact, sur <strong>base indurée</strong>.</li>\n        <li><strong>Ulcération :</strong> lésion creusante sensible <span class=\"kw-alerte\">qui ne guérit pas</span>, bords irréguliers surélevés voire éversés, aspect framboisé, enduit fibrineux, <strong>base indurée dépassant les limites visibles</strong> (valeur quasi-pathognomonique).</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Drapeau rouge.</strong> Toute <span class=\"kw-clinique\">adénopathie cervicale isolée non inflammatoire</span> chez l'adulte (dure/ligneuse/rocailleuse, immobile, ballonisée, comprimant les structures voisines, non inflammatoire) sur terrain alcoolo-tabagique impose <strong>examen ORL + panendoscopie VADS</strong>. <span class=\"kw-alerte\">Biopsie de l'adénopathie interdite</span> en 1ʳᵉ intention. Si tous les examens sont négatifs → cervicotomie exploratrice + analyse extemporanée + TEP-FDG.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 87 — Epistaxis · 88 — Dysphonie - Trouble de la parole · 89 — Altération fonction auditive · 90 — Pathologie des glandes salivaires</em></p>","frequence":16},{"id":"298-6","rang":"B","rubrique":"Contenu multimédia","titre":"Iconographies cliniques typiques des principales formes de carcinome épidermoïde de l'amygdale palatine","contenu":"<p>Le carcinome épidermoïde de l'<span class=\"kw-def\">amygdale palatine</span> est la forme la plus fréquente de cancer de l'oropharynx. Terrain double : alcoolo-tabagique classique <em>ou</em> sujet plus jeune (<span class=\"kw-chiffre\">45-55 ans</span>) <span class=\"kw-etio\">HPV-16+</span> sans intoxication. Aspects cliniques typiques à identifier en photographie :</p>\n      <table >\n        <thead>\n          <tr><th>Forme</th><th>Aspect clinique typique</th><th>Particularités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Forme ulcérée typique</strong></td>\n            <td><span class=\"kw-clinique\">Ulcération indurée</span> du voile mou ou de la luette/uvule, bords irréguliers surélevés, fond fibrineux gris, <strong>saignement au contact</strong>, base indurée à la palpation</td>\n            <td>Forme la plus évocatrice, terrain alcoolo-tabagique +++</td>\n          </tr>\n          <tr>\n            <td><strong>Forme bourgeonnante</strong></td>\n            <td><span class=\"kw-clinique\">Tumeur bourgeonnante ulcérée</span> avec infiltration profonde, friable, hémorragique au contact, base indurée</td>\n            <td>Lésion en volume, sans muqueuse de recouvrement</td>\n          </tr>\n          <tr>\n            <td><strong>Aspect granité</strong></td>\n            <td><span class=\"kw-clinique\">Aspect granité du pôle supérieur</span> de l'amygdale, moins évident à reconnaître</td>\n            <td>Forme trompeuse — biopsie au moindre doute</td>\n          </tr>\n          <tr>\n            <td><strong>Érythème framboisé</strong></td>\n            <td><span class=\"kw-clinique\">Érythème diffus d'aspect framboisé</span> ou au contraire dépoli</td>\n            <td>Diagnostic différentiel : angine chronique → ne régresse pas en quelques jours</td>\n          </tr>\n          <tr>\n            <td><strong>Forme « cachée »</strong></td>\n            <td>Tumeur <span class=\"kw-clinique\">reconnue uniquement à la palpation</span> par induration localisée souvent douloureuse</td>\n            <td>Cachée derrière le pilier antérieur, fond d'un récessus amygdalien, sillon amygdaloglosse</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Asymétrie amygdalienne</strong> chronique unilatérale chez fumeur = drapeau rouge → <span class=\"kw-ci\">ne jamais</span> traiter comme angine banale, <span class=\"kw-alerte\">éliminer une néoplasie</span> par examen ORL + biopsie.</p>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Cet objectif attend une <span class=\"kw-imagerie\">iconographie clinique typique</span> (asymétrie amygdalienne, ulcération du pôle supérieur, aspect granité, érythème framboisé, forme bourgeonnante). La fiche source décrit la sémiologie textuellement — les images photographiques seront ajoutées en B-FIX ultérieur via <code>assets/images/298/</code> avec attribut <code>alt</code> descriptif (Collège ORL, atlas casa anatomique).\n      </div>","frequence":0},{"id":"298-7","rang":"A","rubrique":"Contenu multimédia","titre":"Iconographies cliniques typiques des principales formes de carcinome épidermoïde de la langue","contenu":"<p>Le carcinome épidermoïde de la <span class=\"kw-def\">langue</span> est la forme la plus fréquente du cancer de la cavité buccale. <strong>Examen facile et diagnostic qui devrait être précoce</strong> (langue mobile accessible à l'inspection). Distinguer <strong>langue mobile</strong> (2/3 antérieurs, jusqu'au « V » lingual, examen direct) et <strong>base de langue</strong> (1/3 postérieur, oropharynx, accès indirect par <span class=\"kw-imagerie\">fibroscopie</span>).</p>\n      <table >\n        <thead>\n          <tr><th>Forme</th><th>Aspect clinique typique</th><th>Diagnostic différentiel</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Forme ulcérée</strong></td>\n            <td><span class=\"kw-clinique\">Ulcération chronique</span> à <strong>bords surélevés et indurés</strong> sur le bord libre de langue mobile, persistance <span class=\"kw-alerte\">&gt; 2-3 semaines</span>, base indurée dépassant les limites visibles, douloureuse, saignement au contact</td>\n            <td><span class=\"kw-etio\">Ulcération traumatique</span> sur dent délabrée/prothèse inadaptée → <strong>pas de base indurée</strong>, guérison en <span class=\"kw-chiffre\">10-15 jours</span> après suppression de la cause</td>\n          </tr>\n          <tr>\n            <td><strong>Forme bourgeonnante exophytique</strong></td>\n            <td><span class=\"kw-clinique\">Bourgeon exophytique</span> reposant sur <strong>base indurée ± étendue</strong>, friable, hémorragique</td>\n            <td>Possible carcinome verruqueux secondaire à une LPM</td>\n          </tr>\n          <tr>\n            <td><strong>Formes avancées</strong></td>\n            <td><span class=\"kw-clinique\">Langue fixée</span> au plancher de la bouche, <span class=\"kw-clinique\">perte de mobilité linguale tardive</span>, déviation du côté tumoral à la protraction (XII ou muscles linguaux envahis), gêne à l'alimentation</td>\n            <td>Stade tardif → bilan d'extension obligatoire (<span class=\"kw-imagerie\">TDM</span> + <span class=\"kw-imagerie\">IRM</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Otalgie réflexe</strong></td>\n            <td><span class=\"kw-clinique\">Douleur irradiée à l'oreille</span> homolatérale (V3 — nerf auriculo-temporal)</td>\n            <td>Drapeau rouge : otalgie sans otoscopie pathologique = cancer VADS</td>\n          </tr>\n          <tr>\n            <td><strong>Base de langue</strong></td>\n            <td>Plus discrète : gêne pharyngée unilatérale, dysphagie haute, otalgie réflexe, ADP IIa précoce. <span class=\"kw-alerte\">Souvent HPV+</span></td>\n            <td>Diagnostic tardif (accès indirect — laryngoscopie indirecte/nasofibroscopie)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Cet objectif attend des <span class=\"kw-imagerie\">iconographies cliniques typiques</span> (ulcération chronique du bord libre, bourgeon exophytique, langue fixée tardive). La fiche source décrit la sémiologie textuellement — les images photographiques seront ajoutées en B-FIX ultérieur via <code>assets/images/298/</code> avec attribut <code>alt</code> descriptif (Collège ORL, Collège CMF).\n      </div>","frequence":0},{"id":"298-8","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie d'une leucoplasie de la face interne de joue","contenu":"<p>La <span class=\"kw-def\">leucoplasie (leucokératose)</span> est une <strong>lésion précancéreuse</strong> de la muqueuse buccale. Histologiquement = <span class=\"kw-def\">hyperkératose</span> (accumulation de kératine). <strong>Tabac</strong> = facteur étiologique principal. Localisations préférentielles : plancher buccal, lèvre inférieure, région rétrocommissurale labiale, <strong>face interne de joue</strong>.</p>\n      <table >\n        <thead>\n          <tr><th>Caractéristique</th><th>Leucoplasie</th><th>Diagnostic différentiel</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Aspect typique</strong></td>\n            <td><span class=\"kw-clinique\">Plaque blanchâtre adhérente</span> de la muqueuse buccale, <strong>non détachable au grattage</strong>, surface ± lisse ou inhomogène</td>\n            <td><span class=\"kw-etio\">Candidose</span> : plaques <strong>détachables au grattage</strong>, fond érythémateux ; <span class=\"kw-etio\">lichen plan</span> : réseau de Wickham, stries blanchâtres bilatérales en feuille de fougère ; morsure chronique : ligne dentaire latérale</td>\n          </tr>\n          <tr>\n            <td><strong>Formes homogènes</strong></td>\n            <td>Plaque blanche uniforme, plane, bien limitée</td>\n            <td>Risque de transformation maligne plus faible</td>\n          </tr>\n          <tr>\n            <td><strong>Formes inhomogènes</strong></td>\n            <td>Aspect <span class=\"kw-clinique\">nodulaire</span>, <span class=\"kw-clinique\">érosif</span>, voire <span class=\"kw-clinique\">verruqueux</span> ; <span class=\"kw-clinique\">induration</span> ; <span class=\"kw-clinique\">saignement au contact</span></td>\n            <td><span class=\"kw-alerte\">Plus à risque de transformation maligne</span> → biopsie obligatoire</td>\n          </tr>\n          <tr>\n            <td><strong>Risque de dégénérescence</strong></td>\n            <td>Transformation maligne <span class=\"kw-chiffre\">1-10 %</span> à<span class=\"kw-chiffre\"> 10 ans</span> · plus élevée pour leucoplasie verruqueuse proliférative (papillomatose orale floride, &gt;<span class=\"kw-chiffre\"> 70 ans</span>, femme +++, évolution vers carcinome verruqueux systématique) ou avec dysplasie sévère à la biopsie</td>\n            <td>Érythroplasie de Queyrat : <span class=\"kw-alerte\">dégénérescence systématique</span> (plaques rouges veloutées)</td>\n          </tr>\n          <tr>\n            <td><strong>CAT</strong></td>\n            <td>Biopsie systématique (induration / saignement / inhomogénéité), <strong>sevrage tabagique</strong>, suppression cause traumatique chronique (prothèse mal adaptée), <strong>surveillance régulière</strong> (semestrielle)</td>\n            <td>Lichen plan = surveillance semestrielle aussi (lésion précancéreuse)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Cet objectif attend une <span class=\"kw-imagerie\">photographie clinique typique</span> d'une leucoplasie de la face interne de joue (plaque blanchâtre adhérente non détachable, ± inhomogène/verruqueuse). La fiche source décrit la sémiologie textuellement — l'image photographique sera ajoutée en B-FIX ultérieur via <code>assets/images/298/</code> avec attribut <code>alt</code> descriptif (Collège CMF, atlas dermato-muqueuse).\n      </div>","frequence":0},{"id":"298-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l'indication de l'imagerie devant un cancers VADS","contenu":"<p>Le bilan d'extension d'un cancer des VADS associe <strong>imageries locorégionales et à distance</strong>, complétées d'une <span class=\"kw-def\">panendoscopie</span> systématique (sauf nasosinus et rhinopharynx). Objectifs : préciser l'extension T (locale), N (ganglionnaire), M (métastatique) et rechercher un <strong>cancer synchrone</strong> dans le champ de cancérisation.</p>\n      <table >\n        <thead>\n          <tr><th>Modalité</th><th>Indications · objectifs</th><th>Limites / pièges</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">TDM cervico-thoracique injectée</span></td>\n            <td><strong>Systématique</strong> pour tous les cancers VADS. Locorégional : os, cartilages, ADP. Thoracique : <strong>2ᵉ cancer bronchique synchrone</strong> (champ de cancérisation tabagique) et métastases pulmonaires</td>\n            <td>Moindre résolution sur les parties molles que l'<span class=\"kw-imagerie\">IRM</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">IRM cervico-faciale + base du crâne</span></td>\n            <td><strong>En complément de la <span class=\"kw-imagerie\">TDM</span></strong> pour les tumeurs <strong>au-dessus de l'os hyoïde</strong> : <strong>nasosinus</strong>, <strong>cavum</strong>, <strong>cavité orale avec atteinte linguale</strong>, <strong>oropharynx</strong>. Meilleure résolution sur parties molles, langue, base du crâne, infiltration périnerveuse</td>\n            <td>Seul examen permettant de différencier <strong>tumeur · inflammation · rétention nasosinusienne</strong> induite par la tumeur</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Panendoscopie VADS</span> sous AG</td>\n            <td><strong>Systématique</strong> sauf nasosinus / rhinopharynx (profil épidémio différent). Laryngoscope (cavité buccale, oropharynx, larynx) + hypopharyngoscope. Biopsies si tumeur douloureuse / inaccessible, recherche de <strong>cancers synchrones</strong> des VADS, cartographie de l'extension locorégionale</td>\n            <td>Œsophagoscope / bronchoscope <strong>non systématiques</strong> (sur points d'appel) ; <span class=\"kw-alerte\">cavoscopie ne fait pas partie de la panendoscopie</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">EOGD</span> (<span class=\"kw-imagerie\">fibroscopie œso-gastro-duodénale</span>)</td>\n            <td>Indications : <strong>intoxication alcoolo-tabagique chronique</strong>, localisation <strong>oropharyngée</strong> ou <strong>hypopharyngée</strong> (champ œsophagien)</td>\n            <td><span class=\"kw-alerte\">Inutile</span> dans le cancer du rhinopharynx et nasosinusien</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">TEP-TDM au 18-FDG</span> (jeûne <span class=\"kw-chiffre\">≥ 6 h</span>)</td>\n            <td><strong>Au stade initial :</strong> cancer nasopharyngé · ADP métastatique cervicale de primitif inconnu · VADS à haut risque métastatique (atteinte ganglionnaire <strong>&gt; 1 ganglion unilatéral, soit ≥ N2b</strong>) · formes T3-T4 localement avancées. <br><strong>Après traitement :</strong> évaluation de la réponse, diagnostic des récidives / poursuite évolutive</td>\n            <td>Faux positifs inflammatoires post-RT (attendre 8-12 sem.)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Échographie cervicale</span> + cytoponction</td>\n            <td>ADP cervicales suspectes lorsque les autres examens n'orientent pas — caractérisation et prélèvement cytologique</td>\n            <td>Biopsie chirurgicale de l'ADP <span class=\"kw-alerte\">interdite</span> en 1ʳᵉ intention</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Cas particulier de l'ADP cervicale isolée sans primitif retrouvé</strong> : examen ORL + panendoscopie VADS → si négatifs, <strong>cervicotomie exploratrice</strong> avec exérèse ganglionnaire <em>sans effraction capsulaire</em> + examen extemporané. Si carcinome épidermoïde → curage + <strong>TEP-FDG</strong>. Si fixation pharyngée → refaire <span class=\"kw-imagerie\">endoscopie</span> pour biopsie. Si absence de fixation → <strong>biopsie du cavum</strong> + <strong>amygdalectomie homolatérale</strong> à visée histologique (primitif amygdalien infraclinique fréquent, notamment HPV+).</p>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Mémo bilan VADS : <strong>« Pan-TDM-IRM-TEP »</strong> = <span class=\"kw-imagerie\">Panendoscopie VADS</span> (sauf nasosinus/cavum) + <span class=\"kw-imagerie\">TDM cervicothoracique injectée</span> (systématique) ± <span class=\"kw-imagerie\">IRM</span> (sus-hyoïdien) ± <span class=\"kw-imagerie\">TEP-TDM</span> (cavum, primitif inconnu, ≥ N2b, T3-T4).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 207 — Opacité intra-thoracique Adulte/Enfant · 292 — Diagnostic des cancers</em></p>","frequence":6},{"id":"298-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître les généralités sur la prévention en cancérologie VADS","contenu":"<p>La prévention des cancers VADS repose sur la <strong>lutte contre les facteurs de risque modifiables</strong> (tabac, alcool, HPV, expositions professionnelles) et la <strong>détection précoce des lésions précancéreuses</strong>. Trois niveaux de prévention à organiser.</p>\n      <table >\n        <thead>\n          <tr><th>Niveau</th><th>Mesures</th><th>Cibles · justification</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Prévention primaire</strong> (éviter la maladie)</td>\n            <td>\n              <strong>Sevrage tabagique :</strong> taxation, paquets neutres, prévention en milieu scolaire, accompagnement médical (<span class=\"kw-ttt\">substituts nicotiniques</span>, <span class=\"kw-ttt\">varénicline</span>). <br>\n              <strong>Réduction de l'alcool :</strong> repères ≤ 2 verres/jour, ≤ 10 verres/semaine, <span class=\"kw-chiffre\">≥ 2 jours</span>/sem sans alcool. <br>\n              <strong>Vaccination HPV :</strong> <span class=\"kw-ttt\">Gardasil 9</span> recommandé <strong>filles ET garçons</strong> dès <span class=\"kw-chiffre\">11 ans</span> (schéma 2 doses), rattrapage jusqu'à <span class=\"kw-chiffre\">19 ans révolus</span>, jusqu'à<span class=\"kw-chiffre\"> 26 ans</span> pour HSH. <br>\n              <strong>EPI professionnels :</strong> masques + aspirations collectives pour <span class=\"kw-etio\">bois</span>, <span class=\"kw-etio\">nickel</span>, <span class=\"kw-etio\">formaldéhyde</span>, <span class=\"kw-etio\">amiante</span>, <span class=\"kw-etio\">goudrons</span>. <br>\n              Hygiène bucco-dentaire ; traitement du RGO chronique\n            </td>\n            <td>\n              Tabac + alcool : <span class=\"kw-chiffre\">-2/3 du risque</span> si sevrage (retour au niveau non-fumeur après <span class=\"kw-chiffre\">20 ans</span>). <br>\n              HPV : prévient les cancers oropharyngés HPV-induits (amygdale, base de langue). <br>\n              Exposition pro = <strong>maladies professionnelles</strong> reconnues (poussières de bois, nickel)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Prévention secondaire</strong> (détecter tôt)</td>\n            <td>\n              Consultation <strong>odontologique annuelle</strong> ; éducation du patient sur les signaux d'alarme (<span class=\"kw-alerte\">ulcération chronique &gt; 3 sem, leucoplasie, érythroplasie, dysphonie &gt; 3 sem, otite séreuse unilatérale, adénopathie persistante</span>) ; <span class=\"kw-clinique\">biopsie systématique</span> de toute LPM ; <strong>dépistage opportuniste</strong> chez sujets à risque alcoolo-tabagique (<span class=\"kw-clinique\">examen ORL annuel</span>)\n            </td>\n            <td>Les VADS sont souvent diagnostiqués à un stade tardif → impact direct sur la survie à<span class=\"kw-chiffre\"> 5 ans</span> (<span class=\"kw-chiffre\">35-50 %</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Prévention tertiaire</strong> (limiter complications et récidives)</td>\n            <td>\n              <span class=\"kw-clinique\">Bilan dentaire pré-RT</span> obligatoire (détartrage, avulsion des dents non conservables ou siège de parodontopathie) ; <span class=\"kw-ttt\">fluoration à vie</span> (gouttières) des dents conservées ; avulsions ultérieures sous <span class=\"kw-ttt\">antibioprophylaxie + fermeture muqueuse étanche</span> ; surveillance ORL régulière post-traitement (<span class=\"kw-alerte\">récidive locale</span>, <span class=\"kw-alerte\">2ᵉ cancer métachrone VADS / bronchique</span>) ; prise en charge des séquelles (<span class=\"kw-clinique\">xérostomie</span>, <span class=\"kw-clinique\">trismus</span>, <span class=\"kw-clinique\">dysphagie</span>, <span class=\"kw-clinique\">dysphonie post-RT</span>) ; soutien psychosocial, sevrage alcoolo-tabagique post-cancer (récidive ↓)\n            </td>\n            <td><span class=\"kw-alerte\">Ostéoradionécrose mandibulaire</span> = complication redoutable (<span class=\"kw-chiffre\">3 mois à &gt; 10 ans</span> post-RT), souvent spontanée ou sur geste agressif → prévention bucco-dentaire stricte indispensable</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Tout patient alcoolo-tabagique avec un signe d'appel VADS persistant <span class=\"kw-alerte\">&gt; 3 semaines</span> doit être adressé à un ORL pour examen complet + biopsie. La <strong>vaccination HPV des deux sexes</strong> est un levier de santé publique majeur — atlas-edn lie l'item 298 à l'item 146 (Vaccination) et 300 (col utérin, autre HPV-induit).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction Tabac · 76 — Addiction à l'alcool · 146 — Vaccination · 295 — Prise en charge d'un malade cancéreux</em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.youtube.com/watch?v=uA4B2vhuxXk","label":"Nasofibroscopie"}],"cards":[{"i":"44b8c1fdede6","n":298,"o":"298-1","u":"Définition","t":"Connaître les généralités anatomiques des cancers des voies aérodigestives supérieures (VADS)","q":"Quels sont les trois sites principaux des voies aérodigestives supérieures (VADS) et les structures associées en carcinologie ORL ?","a":"<p>Les trois sites principaux des VADS sont :</p><ul><li>la <strong>cavité orale</strong> ;</li><li>le <strong>pharynx</strong> (nasopharynx/cavum, oropharynx, hypopharynx) ;</li><li>le <strong>larynx</strong>.</li></ul><p>Les <strong>cavités naso-sinusiennes</strong> (fosses nasales, sinus ethmoïdaux, maxillaires, sphénoïdal) leur sont rattachées en termes carcinologiques.</p>"},{"i":"5272c98d79a3","n":298,"o":"298-1","u":"Définition","t":"Connaître les généralités anatomiques des cancers des voies aérodigestives supérieures (VADS)","q":"Quel est le principe général concernant le traitement des aires ganglionnaires dans les cancers des VADS ?","a":"<p>Le principe général est que les cancers des VADS sont <strong>lymphophiles</strong>, ce qui implique que leur traitement comportera <strong>systématiquement</strong> celui des aires ganglionnaires (curage cervical). La seule exception notable est le <strong>cancer glottique T1</strong>, faiblement lymphophile à ses stades précoces.</p>"},{"i":"eab29083497a","n":298,"o":"298-1","u":"Définition","t":"Connaître les généralités anatomiques des cancers des voies aérodigestives supérieures (VADS)","q":"Quelles sont les fonctions physiologiques assurées par les voies aérodigestives supérieures (VADS) ?","a":"<p>Les voies aérodigestives supérieures (VADS) assurent plusieurs fonctions essentielles :</p><ul><li>l'<strong>alimentation</strong> (mastication, déglutition) ;</li><li>l'<strong>articulation</strong> et la <strong>phonation</strong> ;</li><li>la <strong>respiration</strong> ;</li><li>la <strong>protection du poumon</strong> contre les risques d'inhalation.</li></ul>"},{"i":"161ff7898e1c","n":298,"o":"298-10","u":"Prise en charge","t":"Connaître les généralités sur la prévention en cancérologie VADS","q":"Quelles sont les mesures de prévention primaire des cancers VADS ?","a":"<p>Les mesures de prévention primaire des cancers VADS visent à éviter la maladie :</p><ul><li><strong>Sevrage tabagique</strong> (par exemple, substituts nicotiniques, varénicline)</li><li><strong>Réduction de la consommation d'alcool</strong> (repères : &le; 2 verres/jour, &le; 10 verres/semaine, &ge; 2 jours/semaine sans alcool)</li><li><strong>Vaccination HPV</strong> (Gardasil 9 recommandé filles et garçons dès 11 ans, rattrapage jusqu'à 19 ans révolus, jusqu'à 26 ans pour les HSH)</li><li><strong>Équipements de Protection Individuelle (EPI) professionnels</strong> (masques, aspirations collectives) pour les expositions aux toxiques</li><li>Bonne <strong>hygiène bucco-dentaire</strong> et traitement du <strong>RGO chronique</strong></li></ul>"},{"i":"1c188cd2254f","n":298,"o":"298-10","u":"Prise en charge","t":"Connaître les généralités sur la prévention en cancérologie VADS","q":"Quels sont les principaux facteurs de risque modifiables des cancers des voies aéro-digestives supérieures (VADS) ?","a":"<p>Les principaux facteurs de risque modifiables des cancers VADS sont :</p><ul><li>Le <strong>tabac</strong></li><li>L'<strong>alcool</strong></li><li>Le <strong>virus HPV</strong> (Human Papillomavirus)</li><li>Les <strong>expositions professionnelles</strong> (poussières de bois, nickel, formaldéhyde, amiante, goudrons)</li></ul>"},{"i":"790f7b40074a","n":298,"o":"298-10","u":"Prise en charge","t":"Connaître les généralités sur la prévention en cancérologie VADS","q":"Quelles sont les mesures de prévention tertiaire des cancers VADS ?","a":"<p>La prévention tertiaire des cancers VADS vise à limiter les complications et les récidives. Elle inclut :</p><ul><li>Un <strong>bilan dentaire pré-radiothérapie (RT) obligatoire</strong> (détartrage, avulsion des dents non conservables)</li><li><strong>Fluoration à vie</strong> des dents conservées (gouttières)</li><li><strong>Avulsions dentaires ultérieures</strong> sous antibioprophylaxie et fermeture muqueuse étanche</li><li>Une <strong>surveillance ORL régulière post-traitement</strong>, pour dépister une récidive locale ou un second cancer métachrone (VADS ou bronchique)</li><li>La prise en charge des séquelles (xérostomie, trismus, dysphagie, dysphonie post-RT)</li><li>Un <strong>soutien psychosocial</strong> et un <strong>sevrage alcoolo-tabagique post-cancer</strong> pour réduire les récidives</li><li>Prévention de l'<strong>ostéoradionécrose mandibulaire</strong> par une hygiène bucco-dentaire stricte</li></ul>"},{"i":"ac4acbf03e1b","n":298,"o":"298-10","u":"Prise en charge","t":"Connaître les généralités sur la prévention en cancérologie VADS","q":"Quels sont les objectifs et les mesures de prévention secondaire des cancers VADS ?","a":"<p>La prévention secondaire des cancers VADS vise à la détecter tôt et repose sur :</p><ul><li>Une <strong>consultation odontologique annuelle</strong></li><li>L'éducation du patient sur les <strong>signaux d'alarme</strong> (ulcération chronique &gt; 3 semaines, leucoplasie, érythroplasie, dysphonie &gt; 3 semaines, otite séreuse unilatérale, adénopathie persistante)</li><li>La <strong>biopsie systématique</strong> de toute lésion potentiellement maligne (LPM)</li><li>Un <strong>dépistage opportuniste chez les sujets à risque alcoolo-tabagique</strong> (examen ORL annuel)</li></ul><p>L'objectif est d'améliorer la survie, souvent impactée par un diagnostic tardif.</p>"},{"i":"f44744faddbc","n":298,"o":"298-10","u":"Prise en charge","t":"Connaître les généralités sur la prévention en cancérologie VADS","q":"Quand faut-il adresser un patient en consultation ORL pour suspecter un cancer VADS ?","a":"<p>Tout patient <strong>alcoolo-tabagique</strong> présentant un <strong>signe d'appel VADS persistant &gt; 3 semaines</strong> (ulcération, leucoplasie, dysphonie, etc.) doit être adressé à un ORL pour un examen complet et une biopsie.</p>"},{"i":"01510d70b532","n":298,"o":"298-5","u":"Diagnostic positif","t":"Connaître les signes cliniques des cancers de la cavité buccale, des cancers nasosinusiens ou des cancers VADS","q":"Quelles sont les deux formes lésionnelles à reconnaître lors de l'examen clinique des cancers ORL, et quel est leur aspect caractéristique ?","a":"<p>Les deux formes lésionnelles à reconnaître sont : <ul><li><strong>Tumeur bourgeonnante</strong> : Lésion en volume, <strong>sans muqueuse de recouvrement</strong>, friable, hémorragique au contact, sur une <strong>base indurée</strong>.</li><li><strong>Ulcération</strong> : Lésion creusante sensible qui ne guérit pas, avec des <strong>bords irréguliers, surélevés, voire éversés</strong>, un aspect framboisé, un enduit fibrineux, et une <strong>base indurée</strong> dépassant les limites visibles (valeur quasi-pathognomonique).</li></ul></p>"},{"i":"070126d95000","n":298,"o":"298-5","u":"Diagnostic positif","t":"Connaître les signes cliniques des cancers de la cavité buccale, des cancers nasosinusiens ou des cancers VADS","q":"Quels sont les signes cliniques spécifiques pour un cancer du cavum (nasopharynx) ?","a":"<p>Les signes cliniques d'un cancer du cavum sont : <ul><li>Signes rhinologiques (20 %) : <strong>obstruction nasale unilatérale</strong>, épistaxis, rhinorrhée.</li><li>Signes otologiques (25 %) : <strong>otite séreuse unilatérale chez l'adulte</strong> (à considérer comme un cancer du cavum jusqu'à preuve du contraire), hypoacousie de transmission, autophonie, bourdonnements.</li><li>Signes neurologiques (10-15 %) : <strong>paralysies oculomotrices</strong> (envahissement sinus caverneux), <strong>névralgie du V</strong> (foramen ovale, V3), névralgie du IX, <strong>céphalées persistantes</strong>.</li></ul>Les adénopathies sont souvent <strong>cervicales hautes/postérieures, rétromandibulaires-parotidiennes-sous-mastoïdiennes</strong>, et souvent bilataires (50-90 %).</p>"},{"i":"59e7a771c60a","n":298,"o":"298-5","u":"Diagnostic positif","t":"Connaître les signes cliniques des cancers de la cavité buccale, des cancers nasosinusiens ou des cancers VADS","q":"Quels sont les signes cliniques d'un cancer du larynx ?","a":"<p>Le maître symptôme du cancer du larynx est une <strong>dysphonie persistante de plus de 3 semaines</strong> (drapeau rouge). La symptomatologie varie selon la localisation :<ul><li>Glotte : <strong>dysphonie +++</strong>, dyspnée plus tardive. ADP tardives et rares.</li><li>Sus-glotte : dysphagie, gêne pharyngée (signes tardifs et moins évocateurs).</li><li>Sous-glotte : <strong>dyspnée laryngée tardive</strong> (bradypnée inspiratoire + stridor/cornage = urgence thérapeutique).</li></ul></p>"},{"i":"791f1dbc6045","n":298,"o":"298-5","u":"Diagnostic positif","t":"Connaître les signes cliniques des cancers de la cavité buccale, des cancers nasosinusiens ou des cancers VADS","q":"Quels sont les signes cliniques spécifiques et les adénopathies associées pour un cancer de la cavité buccale ?","a":"<p>Pour un cancer de la cavité buccale, les signes cliniques sont : <ul><li>Précoces : <strong>glossodynies</strong>, gêne buccale, douleur, <strong>otalgie réflexe</strong>, odynophagie, gingivorragie.</li><li>Tardifs : <strong>mobilité dentaire</strong> (« dents flottantes » par ostéolyse), instabilité prothétique, <strong>protraction linguale déviée</strong> du côté tumoral, <strong>anesthésie V3</strong> (signe de Vincent) dans les formes gingivomandibulaires, <strong>trismus</strong>, dysarthrie, dysphagie haute.</li></ul>Les adénopathies associées sont des <strong>ADP Ia/Ib sous-mentales/sous-mandibulaires</strong>, dures et ± fixées.</p>"},{"i":"d6b644b253e3","n":298,"o":"298-5","u":"Diagnostic positif","t":"Connaître les signes cliniques des cancers de la cavité buccale, des cancers nasosinusiens ou des cancers VADS","q":"Quels sont les signes cliniques généraux d'alerte devant faire évoquer un cancer des VADS ?","a":"<p>Tout symptôme des VADS persistant <strong>plus de 15 jours</strong> (voire 3 semaines), <strong>fixe</strong>, <strong>unilatéral</strong>, particulièrement sur <strong>terrain alcoolo-tabagique</strong>, doit faire évoquer un cancer. Les signes généraux regroupent la triade « 3D » : <ul><li><strong>Dysphagie</strong></li><li><strong>Dysphonie</strong></li><li><strong>Dyspnée</strong></li></ul>Auxquels s'ajoutent : <ul><li><strong>Douleur</strong></li><li><strong>Otalgie réflexe</strong> (innervation X-IX-V)</li><li><strong>Adénopathie cervicale</strong></li><li><strong>Tuméfaction</strong></li></ul></p>"},{"i":"72dc0994c651","n":298,"o":"298-7","u":"Contenu multimédia","t":"Iconographies cliniques typiques des principales formes de carcinome épidermoïde de la langue","q":"Quelle est l'iconographie clinique typique d'une forme bourgeonnante exophytique de carcinome épidermoïde de la langue ?","a":"<p>L'iconographie clinique typique est un <strong>bourgeon exophytique</strong>, <strong>friable et hémorragique</strong>, reposant sur une <strong>base indurée</strong> plus ou moins étendue.</p>"},{"i":"7c6692b2c8c7","n":298,"o":"298-7","u":"Contenu multimédia","t":"Iconographies cliniques typiques des principales formes de carcinome épidermoïde de la langue","q":"Quelle est l'iconographie clinique typique d'une forme avancée de carcinome épidermoïde de la langue ?","a":"<p>L'iconographie clinique typique d'une forme avancée est une <strong>langue fixée</strong> au plancher de la bouche, entraînant une <strong>perte de mobilité linguale</strong> et une <strong>déviation du côté tumoral à la protraction</strong> (par envahissement des nerfs ou muscles linguaux).</p>"},{"i":"aaeacb77ba7d","n":298,"o":"298-7","u":"Contenu multimédia","t":"Iconographies cliniques typiques des principales formes de carcinome épidermoïde de la langue","q":"Quelle est l'iconographie clinique typique d'une forme ulcérée de carcinome épidermoïde de la langue ?","a":"<p>L'iconographie clinique typique est une <strong>ulcération chronique</strong> (> 2-3 semaines) située sur le <strong>bord libre de la langue mobile</strong>, présentant des <strong>bords surélevés et indurés</strong>, une <strong>base indurée</strong> dépassant les limites visibles et un <strong>saignement au contact</strong>. Elle peut être douloureuse.</p>"}]};